  pdf.setDrawColor(0, 0, 0); // Color negro
  pdf.setLineWidth(0.5); // Grosor de la línea más fina
  const lineStartX2 = 50; // Posición inicial de la línea (mover más a la derecha)
  const lineEndX2 = 100; // Posición final de la línea
