  pdf.setFontSize(9);
  pdf.text("ESMERA SCHOOL, S.L.", titleX, titleY + 6, { align: "center" });

  pdf.setFont("helvetica", "normal");
  pdf.setFontSize(7);
  pdf.setTextColor(0, 0, 0);

